import json
from collections import Counter

d = json.load(open('/root/symb_invariant_consensus/results/sica_expanded_14b.json'))
results = d['results']

# Find all FOLIO problems and check for non-standard answers
standard = {'True', 'False', 'Unknown'}
non_standard = []
for r in results:
    pid = r.get('problem_id', '')
    if not pid.startswith('folio_'):
        continue
    for i, t in enumerate(r.get('per_trace', [])):
        ans = t.get('answer', '')
        if ans not in standard:
            non_standard.append((pid, i, ans))

print(f"Total non-standard answers in FOLIO traces: {len(non_standard)}")
for pid, i, ans in non_standard:
    print(f"  {pid} trace {i}: {repr(ans)}")
